/*
 * Оптомстрой POS · веб-демо · загрузчик pdf.js для пакета printing (fix:pdfcsp; tools/pdfjs-files.mjs).
 *
 * Это НЕ pdf.js. Файл публикуется как pdfjs/pdf.min.js: пакет printing приложения (PdfPreview, Printing.raster) сам
 * вставляет `<script src="${dartPdfJsBaseUrl}pdf.min.js">` (dartPdfJsBaseUrl = 'pdfjs/' задаёт demo-boot.js) и после
 * события load ставит `pdfjsLib.GlobalWorkerOptions.workerSrc`. pdf.js 5 (pdfjs/pdf.min.mjs, pdfjs-dist 5.4.296 без
 * изменений) — только ES-модуль, классическим скриптом его не загрузить; поэтому здесь `pdfjsLib` задаётся сразу, а
 * сам pdf.js подгружается через import() при первом документе (с этого же сайта — CSP без чужих хостов).
 *
 * Пакет вызывает только getDocument(settings) → {promise, destroy} и читает/пишет GlobalWorkerOptions.workerSrc
 * (проверка «pdf.js есть» — workerSrc не пуст). Документ, страницы, render — объекты самого pdf.js.
 * Отличия от прямого вызова pdf.js:
 *   - воркер — всегда pdfjs/pdf.worker.min.mjs этого сайта (значение пакета `…pdf.worker.min.js` не используется);
 *   - data копируется: pdf.js 5 передаёт буфер воркеру (transfer), и байты Uint8List приложения «обнулились» бы;
 *   - isEvalSupported: false — pdf.js не нужен eval (его разрешает CSP только для проверки пакета printing);
 *   - pdf.js 5 при загрузке сам задаёт globalThis.pdfjsLib — загрузчик возвращает на место себя.
 * Классический скрипт ES2017 без `?.`/`??`. Состояние для диагностики — pdfjsLib.__demo.
 */
(function (global) {
  'use strict';

  if (global.pdfjsLib && global.pdfjsLib.__demo) return; // уже загружен

  var script = global.document && global.document.currentScript;
  var base = new URL('.', script && script.src ? script.src : new URL('pdfjs/', global.document.baseURI).href).href;
  var WORKER = base + 'pdf.worker.min.mjs';
  var stats = { version: null, imports: 0, documents: 0, loaded: 0, destroyed: 0, errors: [] };
  var loading = null;
  var facade = null;

  function note(e) {
    var text = String((e && e.message) || e);
    if (stats.errors.length < 20) stats.errors.push(text.slice(0, 300));
    return e;
  }

  function load() {
    if (!loading) {
      stats.imports++;
      loading = import(base + 'pdf.min.mjs').then(
        function (lib) {
          lib.GlobalWorkerOptions.workerSrc = WORKER;
          stats.version = lib.version || null;
          // pdf.js 5 при загрузке сам пишет globalThis.pdfjsLib — пакет и дальше ходит через загрузчик (копия data).
          global.pdfjsLib = facade;
          return lib;
        },
        function (e) {
          loading = null; // следующий документ попробует снова
          throw note(e);
        }
      );
    }
    return loading;
  }

  function source(src) {
    var out = {};
    var k;
    for (k in src) out[k] = src[k];
    if (out.data && typeof out.data.slice === 'function') out.data = out.data.slice();
    if (out.isEvalSupported === undefined) out.isEvalSupported = false;
    return out;
  }

  facade = global.pdfjsLib = {
    GlobalWorkerOptions: { workerSrc: WORKER },
    getDocument: function (src) {
      var task = null;
      var destroyed = false;
      stats.documents++;
      var promise = load()
        .then(function (lib) {
          if (destroyed) throw new Error('pdf.js: документ закрыт до загрузки');
          task = lib.getDocument(source(src || {}));
          return task.promise;
        })
        .then(
          function (doc) {
            stats.loaded++;
            return doc;
          },
          function (e) {
            throw note(e);
          }
        );
      return {
        promise: promise,
        destroy: function () {
          destroyed = true;
          stats.destroyed++;
          return task ? task.destroy() : Promise.resolve();
        },
      };
    },
    __demo: stats,
  };
})(window);
